function goToCandRetosTab(){
  const tabs=document.querySelectorAll('#candDashTabs .dash-tab');
  const retosTab=tabs[1];
  if(retosTab)switchCandTab('common',retosTab);
  setTimeout(function(){
    const grid=document.getElementById('commonExGrid');
    if(grid)grid.scrollIntoView({behavior:'smooth',block:'start'});
  },80);
}
function switchCandTab(tab,btn){
  document.querySelectorAll('#candDashTabs .dash-tab').forEach(t=>t.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('[id^="candTab-"]').forEach(c=>c.classList.remove('active'));
  document.getElementById('candTab-'+tab).classList.add('active');
}

function updateCandProfile(){
  const completed=candidateProfile.completedCommon;
  const scores=completed.map(c=>c.score);
  const avg=scores.length?Math.round(scores.reduce((a,b)=>a+b)/scores.length):0;
  document.getElementById('cDashCompleted').textContent=completed.length;
  document.getElementById('cDashScore').textContent=avg||'—';
  // Posición real en el pool (16-pool-real.js), no un tramo inventado por nota.
  document.getElementById('cDashRank').textContent=(window.TPRanking&&TPRanking.posicionTexto())||'—';
  document.getElementById('spGlobalScore').textContent=avg||'—';
  const softSkills=[];const sectorSkills=[];
  for(const[name,data] of Object.entries(candidateProfile.skills)){
    const ce=COMMON_EXERCISES.find(c=>c.skill===name);
    const cat=ce?.category||'soft';
    if(cat==='soft')softSkills.push({name,data});else sectorSkills.push({name,data});
  }
  function renderSG(skills){
    return skills.map(({name,data})=>{
      const cls=data.unlocked?(data.score>=75?'high':data.score>=50?'mid':'low'):'';
      const color=data.score>=75?'var(--emerald-500)':data.score>=50?'var(--amber-500)':'var(--red-500)';
      const levelLabel=data.score>=80?'Avanzado':data.score>=50?'Intermedio':'Básico';
      const levelCls=data.score>=80?'level-avanzado':data.score>=50?'level-intermedio':'level-basico';
      return '<div class="sp-skill-item '+(data.unlocked?'':'locked')+'"><div class="sp-skill-name">'+name+(data.unlocked?' <span class="sp-skill-score '+cls+'">'+data.score+'</span>':'')+'</div>'+(data.unlocked?'<div style="margin:4px 0 2px"><span class="level-badge '+levelCls+'">'+levelLabel+'</span></div>':'')+'<div class="sp-skill-bar"><div class="sp-skill-bar-fill" style="width:'+(data.unlocked?data.score:0)+'%;background:'+color+'"></div></div></div>';
    }).join('');
  }
  const uS=softSkills.filter(s=>s.data.unlocked);const lS=softSkills.filter(s=>!s.data.unlocked);
  const uSe=sectorSkills.filter(s=>s.data.unlocked);const lSe=sectorSkills.filter(s=>!s.data.unlocked);
  let html='';
  if(uS.length+uSe.length>0){
    html+='<div style="font-size:.65rem;font-weight:700;color:var(--emerald-600);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px">Skills desbloqueados ('+(uS.length+uSe.length)+')</div>';
    html+='<div class="sp-skills-grid" style="margin-bottom:16px">'+renderSG([...uS,...uSe])+'</div>';
  }
  const totalLocked=lS.length+lSe.length;
  if(totalLocked>0){
    const startHidden=totalLocked>12;
    html+='<button type="button" class="btn btn-outline btn-sm sp-pending-toggle" aria-expanded="'+(startHidden?'false':'true')+'" onclick="var g=document.getElementById(\'lockedSkillsGrid\');if(!g)return;var hidden=(g.style.display===\'none\');g.style.display=hidden?\'grid\':\'none\';this.setAttribute(\'aria-expanded\',hidden?\'true\':\'false\');this.textContent=hidden?\'Ocultar skills pendientes ▴\':\'Ver '+totalLocked+' skills pendientes ▾\'">'+(!startHidden?'Ocultar skills pendientes ▴':'Ver '+totalLocked+' skills pendientes ▾')+'</button>';
    html+='<div class="sp-skills-grid" id="lockedSkillsGrid" style="display:'+(startHidden?'none':'grid')+'">'+renderSG([...lS,...lSe])+'</div>';
  }
  document.getElementById('spSkillsGrid').innerHTML=html;
  const matches=getJobMatches();
  document.getElementById('cDashMatches').textContent=matches.filter(m=>m.matchScore===100).length;

  const cta=document.getElementById('candZeroRetosCta');
  const foot=document.getElementById('candProfileFootnote');
  if(cta){
    if(completed.length===0){
      cta.style.display='block';
      if(foot)foot.style.display='none';
      const ver=document.getElementById('candBtnVerRetos');
      const sugBtn=document.getElementById('candBtnStartSuggested');
      if(ver)ver.onclick=function(){goToCandRetosTab();};
      const sug=COMMON_EXERCISES.find(function(c){return !candidateProfile.completedCommon.find(function(x){return x.id===c.id;});});
      if(sugBtn){
        if(sug){
          sugBtn.style.display='inline-flex';
          sugBtn.textContent='Empezar: '+sug.title;
          sugBtn.onclick=function(){openCommonEx(sug.id);};
        }else{
          sugBtn.style.display='none';
        }
      }
    }else{
      cta.style.display='none';
      if(foot)foot.style.display='block';
    }
  }
}

let _dashExCat='all';

function renderCommonExercises(filter='',cat='all'){
  let list=COMMON_EXERCISES;
  // Category filter
  if(cat==='soft')list=list.filter(ce=>ce.category==='soft');
  else if(cat==='sector')list=list.filter(ce=>ce.category==='sector');
  else if(cat==='done')list=list.filter(ce=>candidateProfile.completedCommon.find(c=>c.id===ce.id));
  else if(cat==='pending')list=list.filter(ce=>!candidateProfile.completedCommon.find(c=>c.id===ce.id));
  // Text search
  if(filter){
    const q=filter.toLowerCase();
    list=list.filter(ce=>(ce.title+' '+ce.desc+' '+(ce.searchTerms||'')+' '+ce.skill).toLowerCase().includes(q));
  }
  let html='';
  if(!list.length){
    html='<div style="text-align:center;padding:24px;color:var(--slate-400);grid-column:1/-1"><p>No hay retos que coincidan con tu búsqueda.</p></div>';
  }else{
    list.forEach(ce=>{
      const done=candidateProfile.completedCommon.find(c=>c.id===ce.id);
      const catBadge=ce.category==='sector'?`<span class="cex-tag" style="background:var(--blue-100);color:var(--blue-500);border:1px solid rgba(59,130,246,.15)">Sector</span>`:`<span class="cex-tag universal">Universal</span>`;
      html+=`<div class="common-ex-card ${done?'completed':''}" onclick="openCommonEx('${ce.id}')"><span class="cex-icon">${tpMonograma(ce.title,ce.category)}</span><div class="cex-title">${ce.title}</div><div class="cex-desc">${ce.desc}</div><div class="cex-meta">${catBadge}${ce.tags.filter(t=>t!=='Universal'&&t!=='Sector').map(t=>`<span class="cex-tag">${t}</span>`).join('')}${done?`<span class="cex-tag" style="background:var(--emerald-50);color:var(--emerald-600);border:1px solid var(--emerald-100)">✓ ${done.score}/100</span>`:''}</div></div>`;
    });
  }
  document.getElementById('commonExGrid').innerHTML=html;
}

function filterDashCommonEx(){
  const q=document.getElementById('dashExSearch')?.value||'';
  document.getElementById('dashExClear').classList.toggle('show',q.length>0);
  renderCommonExercises(q,_dashExCat);
}

function setDashExCat(cat,btn){
  _dashExCat=cat;
  document.querySelectorAll('#dashExFilters .filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  filterDashCommonEx();
}

function openCommonEx(id){
  const ce=COMMON_EXERCISES.find(c=>c.id===id);
  if(!ce)return;
  activeJob={id:id,title:ce.title,sector:'Universal',badge:'jb-cognitive',desc:ce.desc,tags:ce.tags,_isCommon:true,_skill:ce.skill};
  currentEx=0;exResults={};_exState={};
  document.getElementById('jmBadge').className='job-badge';
  document.getElementById('jmBadge').textContent='RETO COMÚN';
  document.getElementById('jmBadge').style.cssText='background:var(--emerald-50);color:var(--emerald-600);border:1px solid var(--emerald-100)';
  document.getElementById('jmTitle').textContent=ce.title;
  document.getElementById('jmDesc').textContent=ce.desc;
  const el=ce.exercises;
  document.getElementById('jmProgress').innerHTML=el.map((_,i)=>`<div class="prog-dot${i===0?' active':''}" id="pd${i}"></div>`).join('')+`<span class="prog-lbl">${el.length} ejercicios</span>`;
  document.getElementById('exNav').innerHTML=el.map((e,i)=>`<button class="ex-tab${i===0?' active':''}" onclick="switchEx(${i})"><span class="ex-tab-num">${e.num}</span>${e.title.length>18?e.title.slice(0,18)+'…':e.title}</button>`).join('');
  renderEx(el,0);
  document.getElementById('jobModal').classList.add('open');document.getElementById('jobModal').scrollTop=0;
}

function getJobMatches(){
  return JOBS.map(j=>{
    const req=j.requiredSkills||[];
    const reqLevel=j.requiredLevel||'basico';
    const threshold=reqLevel==='avanzado'?75:reqLevel==='intermedio'?50:30;
    const has=req.filter(s=>{const sk=candidateProfile.skills[s];return sk?.unlocked&&sk.score>=threshold;});
    const missing=req.filter(s=>{const sk=candidateProfile.skills[s];return !sk?.unlocked||sk.score<threshold;});
    const matchScore=req.length?Math.round((has.length/req.length)*100):10;
    const co=COMPANIES.find(c=>c.id===j.company);
    return{...j,matchScore,has,missing,companyName:co?.name||'',companyLogo:co?.logo||'',threshold};
  }).sort((a,b)=>b.matchScore-a.matchScore);
}

function renderJobMatches(){
  const matches=TPEmpleo.filtrar(getJobMatches());
  let html=TPEmpleo.toolbar();
  if(candidateProfile.completedCommon.length===0){
    html=`<div style="text-align:center;padding:32px;background:var(--slate-50);border:1.5px dashed var(--slate-200);border-radius:var(--radius);color:var(--slate-500)"><p style="font-size:2rem;margin-bottom:10px"></p><p style="font-size:.875rem;font-weight:600;margin-bottom:4px">Completa al menos 1 reto común</p><p style="font-size:.78rem">Para calcular tu % de encaje con ofertas, necesitamos conocer tus habilidades primero.</p><button class="btn btn-primary btn-sm" style="margin-top:12px" onclick="switchCandTab('common',document.querySelectorAll('#candDashTabs .dash-tab')[1])">Ir a retos comunes →</button></div>`;
  }else{
    matches.forEach(m=>{
      const req=m.requiredSkills||[];
      const reqLevel=m.requiredLevel||'basico';
      const threshold=m.threshold;
      const hasCount=req.filter(s=>{const sk=candidateProfile.skills[s];return sk?.unlocked&&sk.score>=threshold;}).length;
      const allMet=hasCount===req.length&&req.length>0;
      const cls=allMet?'match-high':hasCount>0?'match-mid':'match-low';
      const pct=req.length?Math.round((hasCount/req.length)*100):0;
      const levelCls='level-'+reqLevel;
      const levelLabel=reqLevel==='avanzado'?'Avanzado':reqLevel==='intermedio'?'Intermedio':'Básico';
      html+=`<div class="match-card" onclick="openJob('${m.id}')">
        <div class="match-score-ring ${cls}">${pct}%</div>
        <div class="match-info">
          <h4>${escHtml(m.title)} <span class="level-badge ${levelCls}" style="vertical-align:middle;margin-left:4px">${levelLabel}</span></h4>
          <div class="match-company">${m.companyLogo} ${m.companyName}</div>
          ${tpCondChips(m)}
          <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:6px">${req.map(s=>{const sk=candidateProfile.skills[s];const ok=sk?.unlocked&&sk.score>=threshold;return`<span class="job-tag" style="font-size:.6rem;border:1px solid ${ok?'var(--emerald-200)':'var(--amber-100)'};background:${ok?'var(--emerald-50)':'rgba(245,158,11,.06)'};color:${ok?'var(--emerald-600)':'var(--amber-500)'}">${ok?'✓':''} ${s}</span>`;}).join('')}</div>
        </div>
        <div class="match-why">${allMet?'✓ Puedes aplicar':' '+hasCount+'/'+req.length}</div>
      </div>`;
    });
  }
  if(candidateProfile.completedCommon.length&&!matches.length)html+='<div style="text-align:center;padding:24px;color:var(--slate-500);font-size:.82rem">Ninguna oferta cumple esos filtros.</div>';
  document.getElementById('candMatchesList').innerHTML=html;
}

